import{_ as t,c as e,o,a4 as a}from"./chunks/framework.BYxathSa.js";const f=JSON.parse('{"title":"Q4：DOCTYPE 的作用是什么？","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q4.md","filePath":"frontend/q4.md","lastUpdated":null}'),n={name:"frontend/q4.md"},r=a('<h1 id="q4-doctype-的作用是什么" tabindex="-1">Q4：DOCTYPE 的作用是什么？ <a class="header-anchor" href="#q4-doctype-的作用是什么" aria-label="Permalink to &quot;Q4：DOCTYPE 的作用是什么？&quot;">​</a></h1><p><code>&lt;!DOCTYPE html&gt;</code> 不是 HTML 标签，而是一句给浏览器的指令。作用是<strong>告诉浏览器以标准模式（Standards Mode）渲染页面，而不是怪异模式（Quirks Mode）</strong>。</p><ul><li><strong>标准模式</strong>：浏览器按照 W3C 标准规范进行渲染，盒模型为 W3C 盒模型（<code>box-sizing: content-box</code>）。</li><li><strong>怪异模式</strong>：为了兼容旧版网页，浏览器会模拟老版本浏览器的行为（如 IE6 的盒模型 <code>border-box</code>），这会导致不同浏览器下页面表现不一致。</li><li>如果遗漏 DOCTYPE 或写法不正确，就可能触发怪异模式，产生不可预期的布局问题。HTML5 只需要 <code>&lt;!DOCTYPE html&gt;</code>。</li></ul>',3),d=[r];function s(c,l,_,i,p,T){return o(),e("div",null,d)}const m=t(n,[["render",s]]);export{f as __pageData,m as default};
